create extension if not exists pgcrypto;
create type user_role as enum ('admin','manager','warehouse','listing');
create type stock_move_type as enum ('receive','sale','reserve','release','move','damage','missing','supplier_return','customer_return','adjustment');
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, role user_role not null default 'warehouse', created_at timestamptz not null default now());
create table if not exists categories(id uuid primary key default gen_random_uuid(), name text not null unique, code text not null unique);
create table if not exists warehouses(id uuid primary key default gen_random_uuid(), name text not null, active boolean not null default true, created_at timestamptz not null default now());
create table if not exists warehouse_locations(id uuid primary key default gen_random_uuid(), warehouse_id uuid not null references warehouses(id), code text not null unique, rack text, bay text, level text, bin text, active boolean not null default true);
create sequence if not exists product_sku_seq start 1000;
create table if not exists products(id uuid primary key default gen_random_uuid(), sku text not null unique, title text not null, category_id uuid references categories(id), brand text, model text, colour text, condition text not null default 'Untested', test_status text not null default 'Not Tested', description text, unit_cost numeric(12,2) not null default 0, target_price numeric(12,2), low_stock_threshold int not null default 2, archived boolean not null default false, created_by uuid references profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists product_images(id uuid primary key default gen_random_uuid(), product_id uuid not null references products(id) on delete cascade, url text not null, is_main boolean not null default false, sort_order int not null default 0, created_at timestamptz not null default now());
create table if not exists inventory_stock(product_id uuid not null references products(id) on delete cascade, location_id uuid not null references warehouse_locations(id), physical_qty int not null default 0 check(physical_qty>=0), reserved_qty int not null default 0 check(reserved_qty>=0 and reserved_qty<=physical_qty), updated_at timestamptz not null default now(), primary key(product_id,location_id));
create table if not exists inventory_movements(id uuid primary key default gen_random_uuid(), product_id uuid not null references products(id), from_location_id uuid references warehouse_locations(id), to_location_id uuid references warehouse_locations(id), movement_type stock_move_type not null, quantity int not null check(quantity>0), reference text, reason text, created_by uuid references profiles(id), created_at timestamptz not null default now());
create table if not exists suppliers(id uuid primary key default gen_random_uuid(), name text not null, contact_name text, phone text, email text, notes text, active boolean not null default true);
create table if not exists purchase_batches(id uuid primary key default gen_random_uuid(), batch_code text not null unique, supplier_id uuid references suppliers(id), purchase_date date, invoice_ref text, total_cost numeric(12,2), notes text, created_at timestamptz not null default now());
create table if not exists sales_channels(id uuid primary key default gen_random_uuid(), name text not null unique, active boolean not null default true);
create table if not exists marketplace_listings(id uuid primary key default gen_random_uuid(), product_id uuid not null references products(id), channel_id uuid not null references sales_channels(id), external_listing_id text, title text, price numeric(12,2), status text, listed_qty int, unique(channel_id,external_listing_id));
create table if not exists orders(id uuid primary key default gen_random_uuid(), order_number text not null unique, channel_id uuid references sales_channels(id), external_order_id text, status text not null default 'New', payment_status text, dispatch_status text, shipping_cost numeric(12,2) not null default 0, marketplace_fee numeric(12,2) not null default 0, created_at timestamptz not null default now());
create table if not exists order_items(id uuid primary key default gen_random_uuid(), order_id uuid not null references orders(id) on delete cascade, product_id uuid not null references products(id), quantity int not null check(quantity>0), unit_price numeric(12,2) not null);
create table if not exists ai_product_analyses(id uuid primary key default gen_random_uuid(), product_id uuid references products(id), image_url text, result jsonb not null, confidence jsonb, model_used text, approved_by uuid references profiles(id), approved_at timestamptz, created_at timestamptz not null default now());
create table if not exists audit_logs(id bigserial primary key, actor_id uuid references profiles(id), action text not null, entity_type text not null, entity_id text, old_value jsonb, new_value jsonb, created_at timestamptz not null default now());
create or replace function available_qty(p_product uuid, p_location uuid) returns int language sql stable as $$ select coalesce(physical_qty-reserved_qty,0) from inventory_stock where product_id=p_product and location_id=p_location $$;
create or replace function reserve_stock(p_product uuid,p_location uuid,p_qty int,p_actor uuid,p_reference text) returns void language plpgsql as $$ begin if p_qty<=0 then raise exception 'Quantity must be positive'; end if; update inventory_stock set reserved_qty=reserved_qty+p_qty,updated_at=now() where product_id=p_product and location_id=p_location and physical_qty-reserved_qty>=p_qty; if not found then raise exception 'Insufficient available stock'; end if; insert into inventory_movements(product_id,from_location_id,movement_type,quantity,reference,reason,created_by) values(p_product,p_location,'reserve',p_qty,p_reference,'Order reservation',p_actor); insert into audit_logs(actor_id,action,entity_type,entity_id,new_value) values(p_actor,'reserve_stock','product',p_product::text,jsonb_build_object('qty',p_qty,'reference',p_reference)); end $$;
create or replace function dispatch_reserved_stock(p_product uuid,p_location uuid,p_qty int,p_actor uuid,p_reference text) returns void language plpgsql as $$ begin update inventory_stock set physical_qty=physical_qty-p_qty,reserved_qty=reserved_qty-p_qty,updated_at=now() where product_id=p_product and location_id=p_location and reserved_qty>=p_qty and physical_qty>=p_qty; if not found then raise exception 'Insufficient reserved stock'; end if; insert into inventory_movements(product_id,from_location_id,movement_type,quantity,reference,reason,created_by) values(p_product,p_location,'sale',p_qty,p_reference,'Dispatch sale',p_actor); insert into audit_logs(actor_id,action,entity_type,entity_id,new_value) values(p_actor,'dispatch_stock','product',p_product::text,jsonb_build_object('qty',p_qty,'reference',p_reference)); end $$;
create index if not exists idx_products_title on products using gin (to_tsvector('english',title));
create index if not exists idx_movements_product_date on inventory_movements(product_id,created_at desc);
